    "<span>Eligibility</span><b>Master Mason, 3°</b>": "<span>Προϋπόθεση</span><b>Διδάσκαλος Τέκτων, 3°</b>",
    "<span>Standing</span><b>Independent Chapter of Widows Sons MRA</b>": "<span>Καθεστώς</span><b>Ανεξάρτητο Chapter των Widows Sons MRA</b>",
